// Shapes of the data the site reads (public/data.json, generated by scripts/build-data.mjs
// from RESEARCH/profiles/*.json and DATABASE/catalog.json). See RESEARCH/profile-template.json.

export type Rating = 5 | 4 | 3 | 2 | 1 | 'against';
export type Verdict = 'supported' | 'partly_true' | 'not_established' | 'contradicted';

export interface Factors {
  study_quality?: string;
  consistency?: string;
  effect_size?: string;
  clinical_significance?: string;
  sample_size?: string;
  population?: string;
  conflicts_of_interest?: string;
  reproducibility?: string;
  formulation_dose?: string;
}

export interface Claim {
  id: string;
  claim: string;
  popular_framing?: string;
  question?: string;
  outcome?: string;
  population?: string;
  rating: Rating;
  verdict: Verdict;
  bottom_line: string;
  what_research_found?: string;
  what_research_did_not_establish?: string;
  limitations?: string;
  formulation_and_dose?: string;
  factors?: Factors;
  myth_feature?: boolean;
  source_ids: string[];
}

export interface FoodRow {
  food: string;
  serving: string;
  amount: number;
  amount_high?: number; // optional upper end when a source gives a range
  unit: string;
  source_id?: string;
}

export interface FoodVsSupplement {
  nutrient: string;
  unit: string;
  foods: FoodRow[];
  research_doses?: { low?: number; high?: number; unit?: string; note?: string; source_ids?: string[] } | null;
  reference_intake?: { amount?: number; unit?: string; label?: string; source_id?: string } | null;
  comparison_note?: string;
  food_advantages?: string;
  when_supplement_may_help?: string;
}

export interface Source {
  id: string;
  type: string;
  title: string;
  authors?: string;
  year?: number | string;
  journal?: string;
  pmid?: string;
  doi?: string;
  url?: string;
  sample_size?: string;
  population?: string;
  intervention?: string;
  findings?: string;
  limitations?: string;
  funding?: string;
  cited_for?: string;
  verification?: { read?: string; via?: string; checked_on?: string; rechecked_on?: string; recheck_result?: string };
}

export interface Profile {
  id: string;
  name: string;
  aliases?: string[];
  category: string;
  outcomes?: string[];
  summary: string;
  description?: string;
  biological_function?: string;
  formulations?: { name: string; notes?: string }[];
  claims: Claim[];
  food_vs_supplement?: FoodVsSupplement | null;
  absorption?: string;
  side_effects?: string;
  interactions?: string;
  cautions?: string;
  upper_limit?: string;
  research_doses_summary?: string;
  related?: string[];
  sources: Source[];
  review_status?: string; // 'draft_ai' until a person signs it off, then 'reviewed'
  reviewed_by?: string;
  reviewed_on?: string; // YYYY-MM-DD
  last_updated?: string;
}

export interface CatalogItem {
  id: string;
  name: string;
  aliases?: string[];
  category: string;
  outcomes?: string[];
  common_claims?: string[];
  priority_score?: number;
  priority_rank?: number;
  sprint?: boolean;
  safety_flag?: string;
}

export interface DataBundle {
  generated: string;
  catalog: CatalogItem[];
  profiles: Profile[];
}
